// runOnceForAllItems — parse Gemini V3, expand per prompt, ENFORCE aspect_ratio from deterministic table.
// Gemini peut halluciner le aspect_ratio → on override selon (Reseau, Format_Post).

const MULTI_IMAGE_FORMATS = new Set(['carrousel']);

// Table déterministe (reseau, format_post) → aspect_ratio (priorité absolue sur Gemini)
function computeAspectRatio(reseau, format) {
  const r = String(reseau || '').toLowerCase();
  const f = String(format || '').toLowerCase();
  // 9:16 — verticaux
  if ((r === 'ig' || r === 'fb') && (f === 'story' || f === 'reel')) return '9:16';
  if (r === 'youtube' && f === 'short') return '9:16';
  if (r === 'tiktok' && (f === 'reel' || f === 'short')) return '9:16';
  // 4:5 — portrait social
  if ((r === 'ig' || r === 'fb') && (f === 'post' || f === 'carrousel')) return '4:5';
  // 1:1 — carré LinkedIn
  if (r === 'linkedin' && (f === 'post' || f === 'carrousel')) return '1:1';
  if (f === 'community_post') return '1:1';
  // 16:9 — paysage
  if (r === 'x' && (f === 'post' || f === 'thread')) return '16:9';
  if (r === 'youtube' && (f === 'video' || f === 'live')) return '16:9';
  if ((r === 'fb' || r === 'linkedin') && f === 'live') return '16:9';
  if (r === 'linkedin' && f === 'video') return '16:9';
  // Default
  return '4:5';
}

const geminiResponses = $input.all();
const sources = $('Airtable — Lire rédigés').all();
const out = [];

function extractJson(t) {
  let c = (t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(c); } catch (e) {}
  const m = c.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}

for (let i = 0; i < geminiResponses.length; i++) {
  const resp = geminiResponses[i].json || {};
  const src = sources[i]?.json || {};
  let text = '';
  if (resp.candidates?.[0]?.content?.parts) text = resp.candidates[0].content.parts.map(p => p.text || '').join('');
  else if (typeof resp === 'string') text = resp;
  else if (resp.content?.parts) text = resp.content.parts.map(p => p.text || '').join('');
  else text = JSON.stringify(resp);

  const data = extractJson(text);
  if (!data || !Array.isArray(data.prompts) || !data.prompts.length) {
    out.push({ json: { id: src.id, _skip: true, error: 'Parse échec ou prompts vides', Status: 'rédigé' }});
    continue;
  }

  const fmt = String(src.Format_Post || '').toLowerCase();
  let prompts = data.prompts;
  if (!MULTI_IMAGE_FORMATS.has(fmt) && prompts.length > 1) prompts = [prompts[0]];

  // OVERRIDE aspect_ratio with deterministic table — ignore whatever Gemini chose
  const enforcedAspectRatio = computeAspectRatio(src.Reseau, src.Format_Post);

  for (let idx = 0; idx < prompts.length; idx++) {
    const p = prompts[idx] || {};
    out.push({ json: {
      id: src.id,
      src_titre: src.Titre,
      src_format: src.Format_Post,
      src_reseau: src.Reseau,
      visual_strategy: data.visual_strategy,
      image_index: p.image_index || (idx + 1),
      total_images: prompts.length,
      prompt_gemini3: p.prompt_gemini3,
      text_overlay: p.text_overlay,
      aspect_ratio: enforcedAspectRatio, // déterministe, pas celui de Gemini
      resolution: '2K',
      model: 'gemini-2.5-flash-image-preview'
    }});
  }
}

return out.length ? out : [{ json: { _empty: true }}];

// runOnceForAllItems — émet 1 item de rendu par slide (carrousel) ou 1 par post (autres formats).
// Direction POSTER. Les carrousels lisent Slides_JSON (cover + points + CTA) -> N images.
const posts = $('Airtable — Lire rédigés').all().map(i => i.json);
let RENDER_CARD_URL = '', RENDER_KEY = '';
try {
  const rc = $('Airtable — Lire Config Render').all().map(i => i.json);
  const g = (k) => { const r = rc.find(x => (x.fields ? x.fields.Cle : x.Cle) === k); return r ? (r.fields ? r.fields.Valeur : r.Valeur) : ''; };
  RENDER_CARD_URL = g('RENDER_CARD_URL'); RENDER_KEY = g('RENDER_KEY');
} catch (e) {}
const ACC = { 'Éducation':'turquoise', 'Inspiration':'violet', 'Produit':'orange', 'Autorité':'corail', 'Communauté':'vert', 'Autre':'orange' };
const FMT = (x) => { x = String(x || '').toLowerCase(); if (['story','reel','short','live'].includes(x)) return '9:16'; if (['community_post','thread'].includes(x)) return '1:1'; return '4:5'; };
const lastWord = (t) => { const w = String(t || '').replace(/[«»"'?!.:;()]/g, '').split(/\s+/).filter((s) => s.length > 3); return w.length ? w[w.length - 1] : ''; };
const out = [];
for (const p of posts) {
  const f = p.fields || p;
  const id = f.id || p.id;
  const accent = ACC[f.Pilier] || 'orange';
  const format = FMT(f.Format_Post);
  const isCar = String(f.Format_Post || '').toLowerCase() === 'carrousel';
  let slides = [];
  try { slides = JSON.parse(f.Slides_JSON || '[]'); } catch (e) {}
  if (isCar && Array.isArray(slides) && slides.length >= 2) {
    const N = Math.min(slides.length, 10);
    slides.slice(0, 10).forEach((s, i) => {
      out.push({ json: { id, image_index: i + 1, total_images: N, visual_strategy: {}, render_url: RENDER_CARD_URL, render_key: RENDER_KEY,
        payload: { template: 'poster', format, title: String(s.titre || f.Titre || '').slice(0, 120), body: String(s.corps || '').slice(0, 170),
          eyebrow: i === 0 ? (f.Pilier || '') : (i + 1) + '/' + N, highlight: lastWord(s.titre || ''), accent, curve: false } } });
    });
  } else {
    out.push({ json: { id, image_index: 1, total_images: 1, visual_strategy: {}, render_url: RENDER_CARD_URL, render_key: RENDER_KEY,
      payload: { template: 'poster', format, title: String(f.Titre || '').slice(0, 120), eyebrow: f.Pilier || '', highlight: lastWord(f.Titre), accent, curve: false } } });
  }
}
return out;

// runOnceForAllItems — groupe par id, collecte les URLs, émet 1 item par contenu
// Status auto/manual selon Config.VALIDATION_MODE (auto → validé, manual → prêt_à_valider)
const items = $input.all().map(i => i.json);
let mode = 'manual';
try {
  const cfg = $('Airtable — Lire VALIDATION_MODE').all().map(i => i.json);
  if (cfg.length && cfg[0].Valeur) mode = String(cfg[0].Valeur).trim().toLowerCase();
} catch(e) {}
const targetStatus = mode === 'auto' ? 'validé' : 'prêt_à_valider';

const byId = {};
for (const it of items) {
  if (!byId[it.id]) byId[it.id] = { id: it.id, urls: [], visual_strategy: it.visual_strategy };
  byId[it.id].urls[it.image_index - 1] = it.public_url;
}
return Object.values(byId).map(g => ({ json: {
  id: g.id,
  Status: targetStatus,
  Visuels_URLs: JSON.stringify(g.urls.filter(Boolean)),
  Visual_Strategy: JSON.stringify(g.visual_strategy || {})
}}));

// runOnceForEachItem — parse Gemini API response, extract base64 image, convert to binary
const resp = $input.item.json;
const meta = $input.item; // to preserve upstream metadata we pass via $('Parse — Stratégie visuelle')
const srcMeta = $('Parse — Stratégie visuelle').all()[$itemIndex].json;

// Extract base64 from Gemini response
let base64 = null;
let mimeType = 'image/png';
const candidates = resp.candidates || [];
for (const c of candidates) {
  const parts = c?.content?.parts || [];
  for (const p of parts) {
    if (p?.inlineData?.data) {
      base64 = p.inlineData.data;
      mimeType = p.inlineData.mimeType || 'image/png';
      break;
    }
  }
  if (base64) break;
}

if (!base64) {
  return { json: { _skip: true, error: 'Gemini response has no inlineData', id: srcMeta.id }};
}

const buffer = Buffer.from(base64, 'base64');
const ext = mimeType.includes('jpeg') ? 'jpg' : 'png';
const fileName = `${srcMeta.id}_${srcMeta.image_index}.${ext}`;
const binary = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return {
  json: {
    id: srcMeta.id,
    image_index: srcMeta.image_index,
    total_images: srcMeta.total_images,
    visual_strategy: srcMeta.visual_strategy,
    aspect_ratio: srcMeta.aspect_ratio,
    fileName: fileName,
  },
  binary: { data: binary }
};

